import{_ as e,o as l,c as o,a5 as s}from"./chunks/framework.DJo0M80U.js";const m=JSON.parse('{"title":"Vue 组件间通信教程","description":"一、父子组件通信 1. 使用 props 和 $emit Vue 2 & Vue 3 父组件传递数据给子组件 ： \\\\<! 父组件 \\\\ \\\\<template\\\\ \\\\<div\\\\ \\\\<child component :myTitle \\"parentTitle\\"\\\\ \\\\</child com。","frontmatter":{"title":"Vue 组件间通信教程","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","项目实战"],"description":"一、父子组件通信 1. 使用 props 和 $emit Vue 2 & Vue 3 父组件传递数据给子组件 ： \\\\<! 父组件 \\\\ \\\\<template\\\\ \\\\<div\\\\ \\\\<child component :myTitle \\"parentTitle\\"\\\\ \\\\</child com。","sidebarWeight":43,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/实战/Vue 组件间通信教程.md"},"headers":[],"relativePath":"posts/Vue系统教程/07-项目实战/Vue 组件间通信教程.md","filePath":"posts/Vue系统教程/07-项目实战/Vue 组件间通信教程.md"}'),g={name:"posts/Vue系统教程/07-项目实战/Vue 组件间通信教程.md"};function r(a,t,n,i,p,d){return l(),o("div",null,[...t[0]||(t[0]=[s('<div><h1 id="vue-组件间通信教程" tabindex="-1">Vue 组件间通信教程 <a class="header-anchor" href="#vue-组件间通信教程" aria-label="Permalink to &quot;Vue 组件间通信教程&quot;">​</a></h1><blockquote><p>本节目标：理解“Vue 组件间通信教程”的核心思路，并能把它用于实际开发或面试表达。 一、父子组件通信</p></blockquote><ol><li>使用 <code>props</code> 和 <code>$emit</code><strong>Vue 2 &amp; Vue 3</strong></li></ol><ul><li><p><strong>父组件传递数据给子组件</strong>： &lt;!-- 父组件 --&gt; &lt;template&gt; &lt;div&gt; &lt;child-component :myTitle=&quot;parentTitle&quot;&gt;&lt;/child-component&gt; &lt;/div&gt; &lt;/template&gt; &lt;script&gt; export default { data() { return { parentTitle: &#39;张三&#39; }; } }; &lt;/script&gt; &lt;!-- 子组件 --&gt; &lt;template&gt; &lt;div&gt;{{ myTitle }}&lt;/div&gt; &lt;/template&gt; &lt;script&gt; export default { props: [&#39;myTitle&#39;] }; &lt;/script&gt;</p></li><li><p><strong>子组件向父组件传递数据</strong>： &lt;!-- 父组件 --&gt; &lt;template&gt; &lt;div&gt; &lt;child-component @message=&quot;handleMessage&quot;&gt;&lt;/child-component&gt; &lt;/div&gt; &lt;/template&gt; &lt;script&gt; export default { methods: { handleMessage(msg) { console.log(&#39;Message from child:&#39;, msg); } } }; &lt;/script&gt; &lt;!-- 子组件 --&gt; &lt;template&gt; &lt;button @click=&quot;sendMessage&quot;&gt;Send Message&lt;/button&gt; &lt;/template&gt; &lt;script&gt; export default { methods: { sendMessage() { this.$emit(&#39;message&#39;, &#39;Hello from child!&#39;); } } }; &lt;/script&gt;</p></li></ul><ol start="2"><li>使用 <code>ref</code> 和 <code>$parent / $children</code><strong>Vue 2 &amp; Vue 3</strong></li></ol><ul><li><strong>父组件访问子组件方法</strong>： &lt;!-- 父组件 --&gt; &lt;template&gt; &lt;div&gt; &lt;child-component ref=&quot;childRef&quot;&gt;&lt;/child-component&gt; &lt;button @click=&quot;accessChildMethod&quot;&gt;Access Child Method&lt;/button&gt; &lt;/div&gt; &lt;/template&gt; &lt;script&gt; export default { methods: { accessChildMethod() { this.$refs.childRef.childMethod(); } } }; &lt;/script&gt; &lt;!-- 子组件 --&gt; &lt;template&gt; &lt;div&gt;Child Component&lt;/div&gt; &lt;/template&gt; &lt;script&gt; export default { methods: { childMethod() { console.log(&#39;Child Method Called&#39;); } } }; &lt;/script&gt; 二、兄弟组件通信</li></ul><ol><li>使用事件总线（Event Bus） <strong>Vue 2</strong> // event-bus.js import Vue from &#39;vue&#39;; export const EventBus = new Vue(); &lt;!-- 兄弟组件一 --&gt; &lt;template&gt; &lt;button @click=&quot;sendMessage&quot;&gt;Send Message&lt;/button&gt; &lt;/template&gt; &lt;script&gt; import { EventBus } from &#39;../event-bus&#39;; export default { methods: { sendMessage() { EventBus.$emit(&#39;message&#39;, &#39;Hello from Sibling One&#39;); } } }; &lt;/script&gt; &lt;!-- 兄弟组件二 --&gt; &lt;template&gt; &lt;div&gt;{{ message }}&lt;/div&gt; &lt;/template&gt; &lt;script&gt; import { EventBus } from &#39;../event-bus&#39;; export default { data() { return { message: &#39;&#39; }; }, created() { EventBus.$on(&#39;message&#39;, (msg) =&gt; { this.message = msg; }); } }; &lt;/script&gt; <strong>Vue 3</strong> // event-bus.js import { createApp } from &#39;vue&#39;; export const EventBus = createApp({}); &lt;!-- 兄弟组件一 --&gt; &lt;template&gt; &lt;button @click=&quot;sendMessage&quot;&gt;Send Message&lt;/button&gt; &lt;/template&gt; &lt;script&gt; import { EventBus } from &#39;../event-bus&#39;; export default { methods: { sendMessage() { EventBus.config.globalProperties.$emit(&#39;message&#39;, &#39;Hello from Sibling One&#39;); } } }; &lt;/script&gt; &lt;!-- 兄弟组件二 --&gt; &lt;template&gt; &lt;div&gt;{{ message }}&lt;/div&gt; &lt;/template&gt; &lt;script&gt; import { EventBus } from &#39;../event-bus&#39;; export default { data() { return { message: &#39;&#39; }; }, created() { EventBus.config.globalProperties.$on(&#39;message&#39;, (msg) =&gt; { this.message = msg; }); } }; &lt;/script&gt; 三、跨级组件通信</li><li>使用 <code>provide/inject</code><strong>Vue 2</strong> &lt;!-- 祖先组件 --&gt; &lt;template&gt; &lt;descendant-component&gt;&lt;/descendant-component&gt; &lt;/template&gt; &lt;script&gt; export default { provide() { return { message: &#39;Hello from Ancestor&#39; }; } }; &lt;/script&gt; &lt;!-- 后代组件 --&gt; &lt;template&gt; &lt;div&gt;{{ message }}&lt;/div&gt; &lt;/template&gt; &lt;script&gt; export default { inject: [&#39;message&#39;] }; &lt;/script&gt; <strong>Vue 3</strong> &lt;!-- 祖先组件 --&gt; &lt;template&gt; &lt;descendant-component&gt;&lt;/descendant-component&gt; &lt;/template&gt; &lt;script&gt; import { provide } from &#39;vue&#39;; export default { setup() { provide(&#39;message&#39;, &#39;Hello from Ancestor&#39;); } }; &lt;/script&gt; &lt;!-- 后代组件 --&gt; &lt;template&gt; &lt;div&gt;{{ message }}&lt;/div&gt; &lt;/template&gt; &lt;script&gt; import { inject } from &#39;vue&#39;; export default { setup() { const message = inject(&#39;message&#39;); return { message }; } }; &lt;/script&gt;</li><li>使用 Vuex <strong>Vue 2 &amp; Vue 3</strong> // store/index.js import { createStore } from &#39;vuex&#39;; export default createStore({ state: { message: &#39;&#39; }, mutations: { setMessage(state, message) { state.message = message; } } }); &lt;!-- 兄弟组件一 --&gt; &lt;template&gt; &lt;button @click=&quot;sendMessage&quot;&gt;Send Message&lt;/button&gt; &lt;/template&gt; &lt;script&gt; export default { methods: { sendMessage() { this.$store.commit(&#39;setMessage&#39;, &#39;Hello from Sibling One&#39;); } } }; &lt;/script&gt; &lt;!-- 兄弟组件二 --&gt; &lt;template&gt; &lt;div&gt;{{ message }}&lt;/div&gt; &lt;/template&gt; &lt;script&gt; export default { computed: { message() { return this.$store.state.message; } } }; &lt;/script&gt; 四、使用 <code>$attrs</code> 和 <code>$listeners</code><strong>Vue 2</strong> &lt;!-- 父组件 --&gt; &lt;template&gt; &lt;child-component v-bind=&quot;$attrs&quot; v-on=&quot;$listeners&quot;&gt;&lt;/child-component&gt; &lt;/template&gt; &lt;!-- 子组件 --&gt; &lt;template&gt; &lt;grandchild-component v-bind=&quot;$attrs&quot; v-on=&quot;$listeners&quot;&gt;&lt;/grandchild-component&gt; &lt;/template&gt; <strong>Vue 3</strong> &lt;!-- 父组件 --&gt; &lt;template&gt; &lt;child-component v-bind=&quot;$attrs&quot; v-on=&quot;$attrs&quot;&gt;&lt;/child-component&gt; &lt;/template&gt; &lt;!-- 子组件 --&gt; &lt;template&gt; &lt;grandchild-component v-bind=&quot;$attrs&quot; v-on=&quot;$attrs&quot;&gt;&lt;/grandchild-component&gt; &lt;/template&gt; 总结 在 Vue 中，组件通信方式有很多，可以根据具体需求选择合适的通信方式。父子组件之间通常使用 <code>props</code> 和 <code>$emit</code>，兄弟组件之间可以通过事件总线，跨级组件可以使用 <code>provide/inject</code> 或 Vuex。对于更复杂的应用场景，Vuex 是一个强大的状态管理工具。希望这个教程能够帮助你更好地理解和应用 Vue 中的组件通信方式。</li></ol></div>',1)])])}const u=e(g,[["render",r]]);export{m as __pageData,u as default};
